import{_ as s,o,c as t,a2 as a}from"./chunks/framework.uw_ZoRon.js";const u=JSON.parse('{"title":"The process model","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/the-process-model.md","filePath":"deep-dive/the-process-model.md"}'),n={name:"deep-dive/the-process-model.md"};function i(r,e,c,d,h,p){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="the-process-model" tabindex="-1">The process model <a class="header-anchor" href="#the-process-model" aria-label="Permalink to &quot;The process model&quot;">​</a></h1><p><strong>In RUSM, a process is a single WebAssembly instance running as a Tokio task</strong> — with its own linear memory (heap), its own stack, and its own set of permitted host functions (syscalls). Nothing is shared with any other process. This one decision is the foundation everything else rests on, so it&#39;s worth seeing why an instance is the right unit.</p><h2 id="why-an-instance-is-the-right-unit" tabindex="-1">Why an instance is the right unit <a class="header-anchor" href="#why-an-instance-is-the-right-unit" aria-label="Permalink to &quot;Why an instance is the right unit&quot;">​</a></h2><p><strong>Isolation gives you fault tolerance.</strong> A trap — a panic, an out-of-bounds access, <code>unreachable</code>, a blown resource limit — unwinds only that one instance. The host catches it and turns it into a process <em>exit</em>; linked processes and supervisors then react (see <a href="/rusm/deep-dive/links-and-supervision">links &amp; supervision</a>). One process crashing can never corrupt another.</p><p><strong>Isolation gives you security.</strong> An instance can call only the host functions, and touch only the resources, it was explicitly granted (see <a href="/rusm/deep-dive/permissions-and-sandboxing">permissions &amp; sandboxing</a>) — default-deny, per process.</p><p><strong>And it&#39;s cheap.</strong> A fresh instance is small and fast to create — a pooling allocator, copy-on-write memory, and a precomputed <code>InstancePre</code> keep spawning on the hot path. RUSM sustains ~440k component spawns/sec (and ~2.4M/sec for native process bodies), with memory bounded per process by Wasmtime store limits. Isolation this cheap is isolation you can afford to use everywhere — a process per request, per connection, per unit of work.</p><h2 id="how-a-process-maps-to-tokio" tabindex="-1">How a process maps to Tokio <a class="header-anchor" href="#how-a-process-maps-to-tokio" aria-label="Permalink to &quot;How a process maps to Tokio&quot;">​</a></h2><p><code>spawn(module)</code> instantiates the module and drives its entry function inside a Tokio task. Because host calls are async under the hood (see <a href="/rusm/deep-dive/fibers-and-blocking-to-async">fibers &amp; blocking→async</a>), a process that &quot;blocks&quot; — waiting on a message, say — simply parks its task and frees the worker thread for another process. The result is hundreds of thousands of concurrent processes multiplexed over a handful of OS threads.</p><blockquote><p>The process <em>abstraction</em> — task + mailbox, an abort-based lifecycle, links and monitors — was first built on native Rust bodies in Phases 1–3. Since Phase 6 a process is a real isolated <strong>Wasm instance</strong> (core module or component); the actor layer above it never changed.</p></blockquote>',9)])])}const m=s(n,[["render",i]]);export{u as __pageData,m as default};
